PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,title TEXT NOT NULL,project TEXT NOT NULL DEFAULT '',cwd TEXT NOT NULL DEFAULT '',platform TEXT NOT NULL DEFAULT 'WSL',provider TEXT NOT NULL DEFAULT 'Codex',model TEXT NOT NULL DEFAULT '',created REAL NOT NULL,updated REAL NOT NULL,archived INTEGER NOT NULL DEFAULT 0,favorite INTEGER NOT NULL DEFAULT 0,parent_id TEXT,message_count INTEGER NOT NULL DEFAULT 0,total_count INTEGER NOT NULL DEFAULT 0,preview TEXT NOT NULL DEFAULT '',metadata TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS sessions_recent ON sessions(updated DESC,id);
CREATE INDEX IF NOT EXISTS sessions_project ON sessions(project,updated DESC,id);
CREATE TABLE IF NOT EXISTS hidden_projects(project TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS session_visibility(session_id TEXT PRIMARY KEY REFERENCES sessions(id),hidden INTEGER NOT NULL CHECK(hidden IN (0,1)));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),identity TEXT NOT NULL,position INTEGER NOT NULL,role TEXT NOT NULL,kind TEXT NOT NULL,phase TEXT NOT NULL DEFAULT '',timestamp REAL NOT NULL,body BLOB NOT NULL,body_hash TEXT NOT NULL,preview TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',UNIQUE(session_id,identity));
CREATE INDEX IF NOT EXISTS messages_session ON messages(session_id,position,id);
CREATE INDEX IF NOT EXISTS messages_role ON messages(session_id,role,position,id);
CREATE VIRTUAL TABLE IF NOT EXISTS search_long USING fts5(text,content='',tokenize='trigram',contentless_delete=1);
CREATE VIRTUAL TABLE IF NOT EXISTS search_short USING fts5(text,content='',detail='none',contentless_delete=1);
CREATE VIRTUAL TABLE IF NOT EXISTS dialogue_long USING fts5(text,content='',tokenize='trigram',contentless_delete=1);
CREATE VIRTUAL TABLE IF NOT EXISTS dialogue_short USING fts5(text,content='',detail='none',contentless_delete=1);
CREATE TABLE IF NOT EXISTS files(path TEXT PRIMARY KEY,session_id TEXT,size INTEGER NOT NULL DEFAULT 0,mtime INTEGER NOT NULL DEFAULT 0,offset INTEGER NOT NULL DEFAULT 0,ordinal INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 0,head_hash TEXT NOT NULL DEFAULT '',tail_hash TEXT NOT NULL DEFAULT '',mode TEXT NOT NULL DEFAULT 'response',last_sync REAL NOT NULL DEFAULT 0,missing INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS raw_chunks(id INTEGER PRIMARY KEY,path TEXT NOT NULL,session_id TEXT,generation INTEGER NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,payload BLOB NOT NULL,UNIQUE(path,generation,start,end));
CREATE TABLE IF NOT EXISTS raw_blobs(digest TEXT PRIMARY KEY,payload BLOB NOT NULL);
CREATE INDEX IF NOT EXISTS raw_session ON raw_chunks(session_id,id);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,mime TEXT NOT NULL,payload BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_runs(id INTEGER PRIMARY KEY,started REAL,finished REAL,report TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS db_items(source TEXT NOT NULL,thread_id TEXT NOT NULL,item_id TEXT NOT NULL,marker TEXT NOT NULL,PRIMARY KEY(source,thread_id,item_id));
PRAGMA user_version=1;
